/** Product page: gallery thumbs, size chips from the hidden Rug Sizes list, quantity stepper, add-to-quote → mhs:quote:add. */
import { on, emit } from "../utils/events.js";
import { qs, qsa } from "../utils/dom.js";
import { stepInput, clamp } from "../utils/stepper.js";

export default function init(root, opts = {}) {
  const dims = qs('[data-mhs="dimensions"]', root);
  const vintage = root.dataset.variant === "vintage" || !!(dims && !dims.closest("[hidden], .w-condition-invisible"));
  // gallery
  const main = qs("[data-mhs-gallery-main]", root); const thumbs = qs("[data-mhs-gallery-thumbs]", root);
  if (thumbs) {
    const live = qsa("[data-mhs-gallery-src]", thumbs).filter((b) => b.dataset.mhsGallerySrc && !b.dataset.mhsGallerySrc.includes("{{"));
    thumbs.hidden = live.length < 2;
    on(thumbs, "click", "[data-mhs-gallery-src]", (_, b) => {
      if (!main) return; main.src = b.dataset.mhsGallerySrc; if (b.dataset.mhsGallerySrcset) main.srcset = b.dataset.mhsGallerySrcset; else main.removeAttribute("srcset");
      qsa("[data-mhs-gallery-src]", thumbs).forEach((x) => { const on_ = x === b; x.classList.toggle("is-active", on_); x.setAttribute("aria-pressed", String(on_)); });
    });
  }
  // sizes (server-rendered hidden list → chips; no timers)
  const sizeBox = qs('[data-mhs="size-options"]', root); const sizeBlock = sizeBox && sizeBox.closest("[data-block]"); const sizeError = qs("[data-mhs-size-error]", root);
  if (sizeBox) {
    const source = qs('[data-mhs="sizes-source"]');
    const names = source ? qsa(".c-pdp__size-name", source).map((n) => n.textContent.trim()).filter((t) => t && !t.includes("{{")) : [];
    sizeBox.replaceChildren();
    names.forEach((t) => { const b = document.createElement("button"); b.type = "button"; b.className = "c-chip"; b.dataset.variant = "size"; b.dataset.mhs = "size-option"; b.dataset.mhsSize = t; b.setAttribute("aria-pressed", "false"); b.textContent = t; sizeBox.appendChild(b); });
    if (sizeBlock) sizeBlock.hidden = vintage || names.length === 0;
    on(sizeBox, "click", '[data-mhs="size-option"]', (_, b) => {
      qsa('[data-mhs="size-option"]', sizeBox).forEach((x) => { const on_ = x === b; x.classList.toggle("is-active", on_); x.setAttribute("aria-pressed", String(on_)); x.classList.remove("is-error"); });
      if (sizeError) sizeError.hidden = true;
    });
  }
  // quantity
  const qtyInput = qs("[data-mhs-qty-input]", root);
  if (qtyInput) {
    if (vintage) qtyInput.max = "1";
    on(root, "click", "[data-mhs-qty-step]", (_, b) => stepInput(qtyInput, Number(b.dataset.mhsQtyStep) || 0));
    qtyInput.addEventListener("change", () => { qtyInput.value = String(clamp(qtyInput.value, Number(qtyInput.min) || 1, Number(qtyInput.max) || Infinity)); });
  }
  // add to quote
  const btn = qs('[data-mhs="add-to-quote"]', root); const feedback = qs("[data-mhs-quote-feedback]", root);
  const selectedSize = () => { const c = sizeBox && qs('[data-mhs="size-option"][aria-pressed="true"]', sizeBox); if (c) return c.dataset.mhsSize || c.textContent.trim(); return dims && !dims.closest("[hidden], .w-condition-invisible") ? (dims.dataset.mhsSize || dims.textContent.trim()) : ""; };
  if (btn) btn.addEventListener("click", () => {
    const needsSize = sizeBlock && !sizeBlock.hidden && qsa('[data-mhs="size-option"]', sizeBox).length > 0;
    const size = selectedSize();
    if (needsSize && !size) { if (sizeError) sizeError.hidden = false; qsa('[data-mhs="size-option"]', sizeBox).forEach((x) => x.classList.add("is-error")); const first = qs('[data-mhs="size-option"]', sizeBox); first && first.focus(); return; }
    const qty = qtyInput ? clamp(qtyInput.value, 1, Number(qtyInput.max) || Infinity) : 1;
    const product = { name: btn.dataset.mhsName || "Rug", collection: btn.dataset.mhsCollection || "", variant: btn.dataset.mhsVariant || "", slug: btn.dataset.mhsSlug || root.dataset.mhsSlug || "", image: btn.dataset.mhsImage || (main && main.currentSrc) || "", size };
    emit("mhs:quote:add", { product, qty, trigger: btn });
    const original = btn.textContent; const added = opts.addedLabel || root.dataset.mhsAddedLabel || "Added ✓";
    btn.textContent = added; if (feedback) feedback.textContent = `${product.name} added to your selection.`;
    setTimeout(() => { btn.textContent = original; }, 2000);
  });
  return { destroy() {} };
}
