/** Numeric stepper shared by the product page and the drawer: clamp and step an <input type=number>. */
export function clamp(value, min = 1, max = Infinity) { const n = Number(value); return Math.min(max, Math.max(min, Number.isFinite(n) ? Math.round(n) : min)); }
export function stepInput(input, delta, { min = Number(input.min) || 1, max = Number(input.max) || Infinity } = {}) {
  input.value = String(clamp((Number(input.value) || min) + delta, min, max));
  input.dispatchEvent(new Event("change", { bubbles: true }));
  return Number(input.value);
}
